#include "instance.h"
#include <algorithm>
namespace rsm{Instance::Instance(std::string c):className_(std::move(c)){}Instance::~Instance()=default;void Instance::SetName(std::string n){if(name_==n)return;name_=std::move(n);PropertyChanged.Fire("Name");}void Instance::SetArchivable(bool v)noexcept{if(archivable_==v)return;archivable_=v;PropertyChanged.Fire("Archivable");}Instance*Instance::SetParent(std::unique_ptr<Instance>c,Instance*p){if(!c||!p||c.get()==p)return nullptr;p->AddChild(std::move(c));return p->children_.back().get();}void Instance::SetParent(Instance*p){if(p==parent_||p==this)return;for(auto*a=p;a;a=a->parent_)if(a==this)return;if(!parent_)return;auto*o=parent_;auto it=std::find_if(o->children_.begin(),o->children_.end(),[this](auto&x){return x.get()==this;});if(it==o->children_.end())return;auto own=std::move(*it);o->children_.erase(it);own->parent_=nullptr;o->ChildRemoved.Fire(this);if(p){own->parent_=p;auto*r=own.get();p->children_.push_back(std::move(own));p->ChildAdded.Fire(r);}}Instance*Instance::FindFirstChild(const std::string&n,bool rec)const{for(auto&c:children_){if(c->Name()==n)return c.get();if(rec)if(auto*x=c->FindFirstChild(n,true))return x;}return nullptr;}Instance*Instance::FindFirstChildOfClass(const std::string&c)const{for(auto&x:children_)if(x->ClassName()==c)return x.get();return nullptr;}std::vector<Instance*>Instance::GetChildren()const{std::vector<Instance*>r;for(auto&c:children_)r.push_back(c.get());return r;}std::vector<Instance*>Instance::GetDescendants()const{std::vector<Instance*>r;for(auto&c:children_){r.push_back(c.get());auto d=c->GetDescendants();r.insert(r.end(),d.begin(),d.end());}return r;}void Instance::AddChild(std::unique_ptr<Instance>c){if(!c||c.get()==this)return;if(c->parent_)c->Destroy();c->parent_=this;c->destroyed_=false;auto*r=c.get();children_.push_back(std::move(c));ChildAdded.Fire(r);}void Instance::Destroy(){if(destroyed_)return;Destroying.Fire();destroyed_=true;while(!children_.empty())children_.back()->Destroy();if(parent_){auto*p=parent_;auto it=std::find_if(p->children_.begin(),p->children_.end(),[this](auto&x){return x.get()==this;});if(it!=p->children_.end()){p->ChildRemoved.Fire(this);p->children_.erase(it);}parent_=nullptr;}}void Instance::CopyStateTo(Instance&c)const{c.name_=name_;c.archivable_=archivable_;c.attributes_=attributes_;}void Instance::CloneChildrenTo(Instance&c)const{for(auto&x:children_)if(auto y=x->Clone()){y->parent_=&c;c.children_.push_back(std::move(y));}}std::unique_ptr<Instance>Instance::Clone()const{if(!archivable_)return nullptr;auto c=std::make_unique<Instance>(className_);CopyStateTo(*c);CloneChildrenTo(*c);return c;}void Instance::SetAttribute(std::string n,AttributeValue v){auto i=attributes_.find(n);if(i!=attributes_.end()&&i->second==v)return;attributes_[n]=std::move(v);AttributeChanged.Fire(n);}const AttributeValue*Instance::GetAttribute(const std::string&n)const{auto i=attributes_.find(n);return i==attributes_.end()?nullptr:&i->second;}}